<?php
declare(strict_types=1);
define('CMS_ROOT', sys_get_temp_dir().'/cms-patch-'.bin2hex(random_bytes(4)));mkdir(CMS_ROOT,0700,true);
require dirname(__DIR__).'/system/core/Bootstrap/autoload.php';
use Cms\Core\Content\{ContentRepository,ContentTypeRegistry,PluginContentService,ContentPublishedEvent,ContentException};
use Cms\Core\Config\Settings;use Cms\Core\Migration\MigrationRunner;use Cms\Core\Rest\ApiV1Controller;use Cms\Core\Http\Request;use Cms\Core\Events\EventDispatcher;use Cms\Core\Plugin\PluginManifest;
$checks=0;function check(bool $ok,string $message):void{global$checks;$checks++;if(!$ok)throw new RuntimeException($message);echo '[PASS] '.$message."\n";}
$p=new PDO('sqlite:'.CMS_ROOT.'/cms.sqlite');$p->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$m=[];foreach(glob(dirname(__DIR__).'/system/migrations/*.php')as$f)$m[]=require$f;(new MigrationRunner($p,$m))->run();
$r=new ContentRepository($p,ContentTypeRegistry::defaults(),[],CMS_ROOT);$events=new EventDispatcher;$seen=[];$events->listen(ContentPublishedEvent::class,function($e)use(&$seen){$seen[]=$e;});$settings=Settings::fromArray(['database'=>['dsn'=>'sqlite:'.CMS_ROOT.'/cms.sqlite'],'site'=>['url'=>'https://isolated.example'],'api'=>['admin_token_sha256'=>hash('sha256','synthetic-test-token')]]);$api=new ApiV1Controller($settings,CMS_ROOT,$events);
$req=fn($method,$id,$body,$extra=[])=>new Request($method,'/api/v1/contents'.($id?'/'.$id:''),[],$body,array_merge(['HTTP_AUTHORIZATION'=>'Bearer synthetic-test-token'],$extra));
$meta=['seo_title'=>'Article title','seo_keywords'=>'article, unique','seo_description'=>'Article description','canonical_url'=>'https://isolated.example/articles/article','paid_content_enabled'=>true,'paid_content_price_minor'=>1234,'paid_content_currency'=>'USD'];
$response=$api->contents($req('POST',0,['title'=>'Article','slug'=>'article','meta'=>$meta,'categories'=>['News'],'tags'=>['CMS'],'task_id'=>'task-create']));$data=json_decode($response->body(),true);$id=$data['data']['item']['id'];check($response->status()===201,'REST authenticated draft create');check(count($seen)===0,'draft emits no published event');
$opaque=$r->find($id)['meta'];$opaque['extension_state']=['owner'=>'keep'];$p->prepare('UPDATE cms_contents SET meta_json=? WHERE id=?')->execute([json_encode($opaque),$id]);
$patch=$api->contents($req('PATCH',$id,['status'=>'published','task_id'=>'task-publish']));check($patch->status()===200,'REST PATCH publishes');check(count($r->termsForContent($id))===2,'omitted categories/tags preserved');check(count($seen)===1&&$seen[0]->taskId==='task-publish'&&$seen[0]->actorType==='api','REST existing event emitted once with safe machine labels');
$api->contents($req('PATCH',$id,['meta'=>['seo_title'=>'Changed']]));$now=$r->find($id);check($now['meta']['paid_content_enabled']&&$now['meta']['paid_content_price_minor']===1234&&$now['meta']['seo_keywords']==='article, unique','flat meta PATCH preserves paid and SEO fields');check($now['meta']['extension_state']===['owner'=>'keep'],'unknown existing extension meta preserved');check(count($seen)===1,'published-to-published same URL does not emit duplicate event');
$d=$r->digest($id);$r->patch($id,['title'=>'Owner edit']);$conflict=$api->contents($req('PATCH',$id,['title'=>'overwrite'],['HTTP_IF_MATCH'=>'"'.$d.'"']));check($conflict->status()===409&&$r->find($id)['title']==='Owner edit','stale If-Match refuses Owner edit atomically');
$response=$api->contents($req('PATCH',$id,['meta'=>['seo_keywords'=>null],'expected_digest'=>$r->digest($id)]));if($response->status()!==200){echo json_encode(['status'=>$response->status(),'error'=>json_decode($response->body(),true)['error']??null])."\n";}check($response->status()===200&&$r->find($id)['meta']['seo_keywords']==='','explicit null clears one meta field to existing default');
$api->contents($req('PATCH',$id,['categories'=>[]]));check(count($r->termsForContent($id))===1&&$r->termsForContent($id)[0]['taxonomy']==='tag','explicit categories empty clears only categories');
$api->contents($req('PATCH',$id,['meta'=>[]]));check($r->find($id)['meta']['paid_content_enabled'],'empty partial meta is no-op');
$api->contents($req('PATCH',$id,['meta_mode'=>'replace','meta'=>['seo_title'=>'replacement']]));check(!$r->find($id)['meta']['paid_content_enabled'],'explicit meta_mode replace retains legacy full replacement contract');
check($api->contents($req('PATCH',$id,['meta'=>null]))->status()===422,'invalid null meta rejected');check($api->contents(new Request('PATCH','/api/v1/contents/'.$id,[],['title'=>'unauthorized']))->status()===401,'unauthenticated update refused');
$before=count($seen);$response=$api->contents($req('PATCH',$id,['status'=>'invalid']));check($response->status()===422&&count($seen)===$before,'failed publication emits no success event');
$manifest=PluginManifest::fromArray(['plugin_id'=>'patch.test','name'=>'Patch','version'=>'1.0.0','author'=>'Test','core'=>['min'=>'1.2.0'],'php'=>'8.3','entry'=>'entry.php','capabilities'=>['content.read','content.write']]);$plugin=new PluginContentService($manifest,$r,null,$events,$settings);
$item=$plugin->createDraft(['title'=>'Plugin','slug'=>'plugin','meta'=>$meta,'categories'=>['News'],'tags'=>['CMS'],'task_id'=>'plugin-task']);$plugin->publish($item['id']);check(count($r->termsForContent($item['id']))===2,'plugin publish preserves terms');$plugin->update($item['id'],['meta'=>['seo_title'=>'plugin SEO'],'task_id'=>'plugin-update']);check($r->find($item['id'])['meta']['paid_content_enabled'],'plugin partial meta preserves paid fields');check(count($seen)===$before+1,'plugin publish emits one existing event; update does not duplicate');
$log=$p->query("SELECT context_json FROM cms_audit_logs WHERE actor_type='plugin' ORDER BY id DESC LIMIT 1")->fetchColumn();check(str_contains($log,'plugin-update')&&str_contains($log,'patch.test')&&!str_contains($log,'synthetic-test-token'),'plugin audit traces task and plugin; no token');
$symlink=CMS_ROOT.'-link';symlink(CMS_ROOT,$symlink);try{$bad=new ContentRepository($p,ContentTypeRegistry::defaults(),[],$symlink);$bad->create('article','bad','bad',[]);check(false,'symlink root allowed');}catch(ContentException){check(true,'symlink root fails closed');}unlink($symlink);
$other=CMS_ROOT.'-other';mkdir($other);symlink($other,CMS_ROOT.'/content/uploads-escape');rename(CMS_ROOT.'/content/uploads',CMS_ROOT.'/content/uploads-real');rename(CMS_ROOT.'/content/uploads-escape',CMS_ROOT.'/content/uploads');try{$r->create('article','escape','escape',[]);check(false,'uploads link allowed');}catch(ContentException){check(true,'symlink uploads fails closed before database write');}unlink(CMS_ROOT.'/content/uploads');rename(CMS_ROOT.'/content/uploads-real',CMS_ROOT.'/content/uploads');check($r->adminCount()===2,'failed roots create no article');
check((new ContentPublishedEvent(1,'article','T','t','/articles/t','https://isolated.example/articles/t','now','created'))->taskId===null,'old event constructor remains compatible');
$media=new \Cms\Core\Media\LocalMediaStorageProvider(CMS_ROOT.'/content/uploads');symlink($other,CMS_ROOT.'/content/uploads/nested-escape');try{$media->path('nested-escape/a.png');check(false,'nested media symlink accepted');}catch(\Cms\Core\Media\MediaException){check(true,'nested media symlink rejected');}unlink(CMS_ROOT.'/content/uploads/nested-escape');
echo "Content PATCH release regressions: $checks PASS\n";
